export type Language = "en" | "pt";
export type Layout = "single-column" | "two-columns" | "canva-like" | "latex-like" | "linkedin-export";

export interface Period {
  start: string;
  end: string | null;
}

export interface ExperienceData {
  role: string;
  company: string;
  location: string;
  period: Period | null;
  bullets: string[];
  companyFirst?: boolean;
}

export interface EducationData {
  institution: string;
  degree: string;
  period: Period;
}

export interface ProjectData {
  name: string;
  description: string;
  url: string | null;
}

export interface CertificationData {
  name: string;
  issuer: string;
  year: number;
}

// Ways a resume departs from the plain order of its layout: the education before the
// experience, no skills section at all, the languages written on one labelled line under the
// summary, and the certifications written on one labelled line at the end of the experience.
export interface Variants {
  educationFirst?: boolean;
  noSkillsSection?: boolean;
  languagesInline?: boolean;
  certificationsInExperience?: boolean;
}

export interface Person {
  slug: string;
  language: Language;
  layout: Layout;
  variants?: Variants;
  name: string;
  headline: string;
  location: string;
  email: string;
  phone: string;
  linkedin: string;
  github: string | null;
  website: string | null;
  summary: string;
  experiences: ExperienceData[];
  education: EducationData[];
  skills: string[];
  projects: ProjectData[];
  languages: string[];
  certifications: CertificationData[];
}

